import type { Record, TableName, TableSchemaDotWalk } from '../db'

type maxValue =
    | {
          /** @deprecated */
          max_value?: boolean
          maxValue?: never
      }
    | {
          maxValue?: boolean
          max_value?: never
      }

type minValue =
    | {
          /** @deprecated */
          min_value?: boolean
          minValue?: never
      }
    | {
          minValue?: boolean
          min_value?: never
      }

type averageValue =
    | {
          /** @deprecated */
          average_value?: boolean
          averageValue?: never
      }
    | {
          averageValue?: boolean
          average_value?: never
      }

type ListElement<T extends TableName> = {
    /** Field to display in the column */
    element: TableSchemaDotWalk<T> | (string & {})
    sum?: boolean
    position?: number
} & maxValue &
    minValue &
    averageValue

export type List<T extends TableName = TableName> = {
    /** @deprecated List IDs are now derived from the other fields. The explicit $id is no longer used. */
    $id?: Now.Internal.ExplicitKey | string | number
    /**Name of the table for the list */
    table: T
    /**An array of columns in the table to display in the list */
    columns: Array<ListElement<T>['element'] | ListElement<T>>
    /**The UI view (sys_ui_view) to apply to the list (reference record or name of the UI View) */
    view: Record<'sys_ui_view'> | string
    /**The table on which the related list appears */
    parent?: TableName
    /**The relationship to apply to the related list */
    relationship?: Record<'sys_relationship'> | string
} & Now.Internal.Meta

/**
 * Creates a list view for tables (`sys_ui_list`)
 *
 * @see https://docs.servicenow.com/csh?topicname=list-api-now-ts.html&version=latest
 *
 * @param config - an object containing the following properties:
 *   * **table** - name of the table for the list
 *   * **columns** - an array of columns in the table to display in the list
 *   * **view** - the UI view (`sys_ui_view`) to apply to the list
 *   * **parent** - the table on which the related list appears
 *   * **relationship** - the relationship (`sys_relationship`) to apply to the related list
 *
 * Note: It's not recommended to update the list directly from sys_ui_list table. Instead, use the `List Layout` editor to create/update lists on instance.
 */
export function List<const T extends TableName>(config: List<T>) {
    return config
}
